/**
 * 全螢幕雷達拉近時寫的地標（v1.698 使用者說地圖拉近可以放地標，例如大巨蛋、公園）：[名稱, 緯度, 經度, 種類, 外框大約幾公頃]。
 * 來源：OpenStreetMap（© OpenStreetMap contributors，ODbL），2026-11-13 用 Overpass 抓一次：
 * 1. 有 Wikidata 的（比較有名的）公園、體育場、博物館美術館圖書館展演、大學、市政府、動物園遊樂園水族館、古蹟、景點；同一個 Wikidata 只留一筆。
 * 2. 沒有 Wikidata、有名字的公園（種類 lpark；v1.701 使用者說萬芳四號公園看不到）：同名、300 m 內的合成一筆。
 * 3. 國小（es）、國中（jh，含國中小）、高中職（hs）：2026-11-14 抓有名字的 amenity=school（v1.724 使用者說學校都寫出來），
 *    名字縮短成「龍安國小」「建國高中」「大安高工」，同名、600 m 內的合成一筆；跟教育部 114 學年度名錄比對，國中 99%、國小 96%、高中職 90% 對得上
 *    （對不上的多半是寫法不同）。大學照第 1 種（school）。
 * 位置是外框的中間（點的就是那一點）；名稱有括號的，本名太長或括號裡是常用的名字（「桃園巨蛋」「北美館」）就用括號裡的；
 * 外框超過 2 萬公頃的（國家公園、整座島）不收。公頃是外框的面積（不是真的面積），只用來排誰先寫。全螢幕、拉近時才載入
 */
